// Function to reverse a row
void reverseRow(int n, int row[]) {
    int start = 0, end = n - 1;
    while (start < end) {
        int temp = row[start];
        row[start] = row[end];
        row[end] = temp;
        start++;
        end--;
    }
}

// Function to rotate the matrix
void rotateMatrix(int n, int mat[n][n]) {
    // Step 1: Reverse each row
    for (int i = 0; i < n; i++) {
        reverseRow(n, mat[i]);
    }

    // Step 2: Transpose the matrix
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            int temp = mat[i][j];
            mat[i][j] = mat[j][i];
            mat[j][i] = temp;
        }
    }
}

